const originalCode = `package cache\n\nimport (\n    "sync"\n    "time"\n)\n\ntype Store struct {\n    mu      sync.RWMutex\n    entries map[string]Entry\n}\n\n// Load returns a cached value for key.\nfunc (s *Store) Load(key string) ([]byte, bool) {\n    s.mu.RLock()\n    defer s.mu.RUnlock()\n\n    entry, ok := s.entries[key]\n    if !ok {\n        return nil, false\n    }\n\n    return entry.Value, true\n}`;
