function pageHeading(title, subtitle = '', actions = '', eyebrow = '') {
  return `<div class="page-heading"><div>${eyebrow ? `<div class="eyebrow">${eyebrow}</div>` : ''}<h1>${title}</h1>${subtitle ? `<p>${subtitle}</p>` : ''}</div><div class="heading-actions">${actions}</div></div>`;
}
function panel(title, body, action = '') { return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`; }
function notice(message, tone='info', action='') { return `<div class="notice ${tone}" role="status">${icon(tone === 'error' ? 'warning' : 'clock')}<div>${message}</div>${action}</div>`; }
function meta(label,value) { return `<div class="meta-item"><span>${label}</span><strong>${value}</strong></div>`; }
function emptyState(title, message, action='', symbol='inbox') { return `<div class="panel empty">${icon(symbol)}<h2>${title}</h2><p>${message}</p>${action}</div>`; }
function stepper(current) { return `<nav class="stepper" aria-label="Change progress">${[['assistant','Request'],['draft','Draft'],['checks','Checks'],['review','Review'],['receipt','Applied']].map(([id,label],i)=>`<a href="#${id}" class="step ${i===current?'current':i<current?'done':''}" ${i===current?'aria-current="step"':''}><span class="step-number">${i<current?'✓':i+1}</span>${label}</a>`).join('')}</nav>`; }
function paintCode(line) {
  return line.split(/("(?:\\.|[^"\\])*"|\/\/.*$|\b(?:package|import|type|struct|func|return|if|defer|for|range|nil|true|false|var|make|select|case)\b)/g).map((part,index)=>index%2?`<span class="${part.startsWith('//')?'comment':part.startsWith('"')?'str':'kw'}">${esc(part)}</span>`:esc(part)).join('');
}
function sourceCode(code=originalCode, start=1, highlight=0) { return `<pre aria-label="Read-only source">${code.split('\n').map((line,i)=>`<span class="code-line ${i+start===highlight?'highlight':''}"><span class="line-no">${i+start}</span>${paintCode(line)}</span>`).join('')}</pre>`; }
function codePanel(path=state.editorFile, code=originalCode, start=1, highlight=0) { return `<div class="code-block"><div class="code-title"><span>${esc(path)}</span>${badge('Read-only')}</div>${sourceCode(code,start,highlight)}</div>`; }
