function fileRows() { const matching=files.filter(([path,status])=>path.toLowerCase().includes(state.fileQuery.toLowerCase()) && (state.fileFilter==='All files'||state.fileFilter==='Excluded'&&!state.selectedFiles.has(path)||state.fileFilter==='Outdated'&&status==='Outdated'));return matching.map(([path,status,language])=>`<tr><td><input type="checkbox" data-file="${path}" aria-label="Include ${path}" ${state.selectedFiles.has(path)?'checked':''} ${analysisLocked()?'disabled':''}></td><td class="path"><a href="#editor" data-source="${path}">${path}</a></td><td class="secondary">${language}</td><td>${badge(state.selectedFiles.has(path)?status:'Excluded',state.selectedFiles.has(path)?status==='Current'?'green':status==='Outdated'?'amber':'':'')}</td></tr>`).join('') || '<tr><td colspan="4">No matching files.</td></tr>'; }
