  return `<div class="page">${pageHeading('Analysis run',`${esc(state.project)} · ${state.runTotal} selected files`,actions)}<div class="tabs"><a href="#analysis" class="tab">Files</a><a href="#analysis-run" class="tab active">Run</a><a href="#scan" class="tab">Verified scan</a></div><section class="panel"><div class="run-overview"><div class="row"><span class="finding-mark ${running?'blue':''}">${icon(running?'activity':paused?'pause':'circleCheck')}</span><div><h2>${status}</h2><p class="small">${running?'Reviewing internal/cache/store.go':paused?'Run paused. Completed results are available.':finished?'All selected files processed.':'Completed results retained.'}</p></div></div><div class="run-stat">${count}<span class="number-unit">/ ${state.runTotal} files</span></div></div><div class="run-progress"><div class="row between"><span>${Math.round(count/Math.max(1,state.runTotal)*100)}% processed</span><span>Started 10:44 · 2m 18s elapsed</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,count/Math.max(1,state.runTotal)*100)}%"></div></div></div></section><div class="grid three-columns section-gap">${[['Bugs','bugs',3],['Performance','performance',2],['Security','security',1]].map(([name,id,n])=>`<a href="#${id}" class="panel panel-pad"><div class="row between"><h2>${name}</h2>${icon('upRight')}</div><div class="metric-number">${n}</div><span class="small muted">${name==='Security'?'1 source-rule finding':'Results available'}</span></a>`).join('')}</div><div class="section-gap">${panel('Activity',`${[['circleCheck','internal/api/middleware.go','Completed','10:46:18'],['circleCheck','internal/config/config.go','Completed','10:46:04'],['circleCheck','cmd/harbor/main.go','Completed','10:45:52'],['warning','internal/api/server.go','Partial · response limit','10:45:33']].map(([symbol,path,result,time])=>`<div class="activity-row">${icon(symbol)}<div><span class="mono small">${path}</span><p class="small muted">${result}</p></div><span class="time">${time}</span></div>`).join('')}`)}</div></div>`;
