function draftDiff() {
  const before=state.originalDeclaration?state.originalDeclaration.split('\n'):[],after=state.draft.split('\n');
  let prefix=0,suffix=0;
  while(prefix<before.length&&prefix<after.length&&before[prefix]===after[prefix])prefix++;
  while(suffix<before.length-prefix&&suffix<after.length-prefix&&before[before.length-1-suffix]===after[after.length-1-suffix])suffix++;
  return {prefix,suffix,before,after,removed:before.slice(prefix,before.length-suffix),added:after.slice(prefix,after.length-suffix)};
}
function diffContent() {
  if(state.diffMode==='Split') return `<div class="split-diff"><div><div class="code-title">Original</div>${sourceCode(state.originalDeclaration,14)}</div><div><div class="code-title">Draft</div>${sourceCode(state.draft,14)}</div></div>`;
  const diff=draftDiff();
  const row=(line,type,number)=>`<span class="code-line ${type}"><span class="line-no">${number}</span>${paintCode(line)}</span>`;
  return `<pre aria-label="Read-only composed diff">${diff.before.slice(0,diff.prefix).map((line,i)=>row(line,'',i+14)).join('')}${diff.removed.map(line=>row(line,'remove','−')).join('')}${diff.added.map(line=>row(line,'add','+')).join('')}${diff.after.slice(diff.after.length-diff.suffix).map((line,i)=>row(line,'',14+diff.after.length-diff.suffix+i)).join('')}</pre>`;
}
